// LoginState is the outcome of a login step.
type LoginState int

const (
	// LoggedIn means the tokens were stored.
	LoggedIn LoginState = iota
	// NeedsMFA means Garmin sent a code; call Session.SubmitMFA.
	NeedsMFA
)

// stepTimeout bounds each login step; Garmin's SSO normally answers in a few
// seconds.
const stepTimeout = 90 * time.Second

// Session is a login waiting for the MFA code. Garmin keeps the MFA state in
// the memory of the running login, so the garmin-fetch process stays alive
// until the code arrives or the session expires.
type Session struct {
	p      *process
	cancel context.CancelFunc
}

// Login starts a login with e-mail and password. The password is written to
// garmin-fetch's stdin and never stored. If Garmin asks for a code, the
// returned session must be completed with SubmitMFA or closed; it expires
// after expiry.
func (r *Runner) Login(email, password string, expiry time.Duration) (LoginState, *Session, error) {
	if err := os.MkdirAll(r.TokenDir, 0o700); err != nil {
		return 0, nil, err
	}
	// Not bound to the HTTP request: the process must survive until the MFA code.
	ctx, cancel := context.WithTimeout(context.Background(), expiry)
	p, err := r.start(ctx, "login")
	if err != nil {
		cancel()
		return 0, nil, err
	}
	s := &Session{p: p, cancel: cancel}
	if err := s.writeLine(map[string]string{"email": email, "password": password}); err != nil {
		s.Close()
		return 0, nil, err
	}
	state, err := s.next()
	if err != nil || state == LoggedIn {
		s.Close()
		return state, nil, err
	}
	return NeedsMFA, s, nil
}

// SubmitMFA completes the login with the code Garmin sent.
func (s *Session) SubmitMFA(code string) error {
	defer s.Close()
	if err := s.writeLine(map[string]string{"mfa_code": code}); err != nil {
		return err
	}
	state, err := s.next()
	if err == nil && state != LoggedIn {
		err = fmt.Errorf("unexpected second MFA request")
	}
	return err
}

// Close ends the session. Closing stdin lets garmin-fetch exit on its own
// (it was either done or waits for the MFA line); the context deadline kills
// it if it does not.
func (s *Session) Close() {
	s.p.stdin.Close()
	for range s.p.events {
		// Drain so the reader goroutine ends.
	}
	_ = s.p.cmd.Wait()
	s.cancel()
}

func (s *Session) writeLine(v any) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	_, err = s.p.stdin.Write(append(b, '\n'))
	return err
}

// next waits for the outcome of the current step.
func (s *Session) next() (LoginState, error) {
	timer := time.NewTimer(stepTimeout)
	defer timer.Stop()
	var lastErr *Event
	for {
		select {
		case ev, ok := <-s.p.events:
			if !ok {
				err := s.p.wait(lastErr)
				if err == nil {
					err = errors.New("garmin-fetch ended without result")
				}
				return 0, err
			}
			switch ev.Event {
			case "login_ok":
				return LoggedIn, nil
			case "mfa_required":
				return NeedsMFA, nil
			case "error":
				e := ev
				lastErr = &e
			}
		case <-timer.C:
			return 0, errors.New("Zeitüberschreitung bei der Anmeldung")
		}
	}
}
